521		// No checkpoint_remote configured — origin holds the checkpoint store. Origin
522		// only tracks Primary when Primary is in Push.
523		var remoteRef *plumbing.Reference
524		if refs.PrimaryFetchableFromOrigin() {
525			var remoteErr error
526			remoteRef, remoteErr = repo.Reference(plumbing.NewRemoteReferenceName("origin", primaryName), true)
527			if remoteErr != nil && !errors.Is(remoteErr, plumbing.ErrReferenceNotFound) {
528				return fmt.Errorf("failed to check remote metadata ref: %w", remoteErr)
529			}
530		}
531	
532		if localExists {
533			if remoteRef != nil && localRef.Hash() != remoteRef.Hash() {
534				// Local and remote exist but differ — determine relationship
535				hasData, checkErr := metadataBranchHasData(repo, localRef)
536				if checkErr != nil {
537					return fmt.Errorf("failed to check metadata ref contents: %w", checkErr)
538				}
539				if !hasData {
540					// Un-initialized orphan — just point to remote
541					if setErr := setRefHash(repo, refs.Primary, remoteRef.Hash()); setErr != nil {
542						return fmt.Errorf("failed to update metadata ref from remote: %w", setErr)
543					}
544					fmt.Fprintf(os.Stderr, "[entire] Updated local ref '%s' from origin\n", primaryName)
545				} else {
546					// Local has real data and differs from remote — if disconnected
547					// (no common ancestor), reconciliation happens at pre-push time
548					// or via 'entire doctor'. Read paths warn but do not auto-fix.
549					logging.Debug(ctx, "metadata ref differs from remote, reconciliation deferred to read/write time",
550						"local_hash", localRef.Hash().String()[:7],
551						"remote_hash", remoteRef.Hash().String()[:7],
552					)
553				}
554			}
555			return nil
556		}
