571	// createOrphanMetadataRef creates the local primary metadata ref as a fresh empty
572	// orphan commit (plus any merged vercel config). Used when no metadata ref can be
573	// sourced from origin or a checkpoint_remote.
574	func createOrphanMetadataRef(ctx context.Context, repo *git.Repository, refs checkpoint.PersistentRefs) error {
575		emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
576		obj := repo.Storer.NewEncodedObject()
577		if err := emptyTree.Encode(obj); err != nil {
578			return fmt.Errorf("failed to encode empty tree: %w", err)
579		}
580		emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
581		if err != nil {
582			return fmt.Errorf("failed to store empty tree: %w", err)
583		}
584		emptyTreeHash, err = vercelconfig.MaybeMergeMetadataBranchConfig(repo, emptyTreeHash)
585		if err != nil {
586			return fmt.Errorf("failed to initialize metadata ref vercel config: %w", err)
587		}
588	
589		// Create orphan commit (no parent)
590		now := time.Now()
591		authorName, authorEmail := GetGitAuthorFromRepo(repo)
592		sig := object.Signature{
593			Name:  authorName,
594			Email: authorEmail,
595			When:  now,
596		}
597	
598		commit := &object.Commit{
599			TreeHash:  emptyTreeHash,
600			Author:    sig,
601			Committer: sig,
602			Message:   "Initialize metadata ref\n\nThis ref stores session metadata.\n",
603		}
604		// Note: No ParentHashes - this is an orphan commit
605	
606		// Sign the orphan commit when signing is enabled, matching the path used
607		// for every other metadata commit (see metadata_reconcile.go and
608		// push_common.go). Without this, repos that enforce a "verified
609		// signatures" ruleset on entire/* refs reject the very first push of
610		// the metadata ref with GH013, even though every later commit on it
611		// is correctly signed.
612		checkpoint.SignCommitBestEffort(ctx, commit)
613	
614		commitObj := repo.Storer.NewEncodedObject()
615		if err := commit.Encode(commitObj); err != nil {
616			return fmt.Errorf("failed to encode orphan commit: %w", err)
617		}
618		commitHash, err := repo.Storer.SetEncodedObject(commitObj)
619		if err != nil {
620			return fmt.Errorf("failed to store orphan commit: %w", err)
621		}
622	
623		if err := setRefHash(repo, refs.Primary, commitHash); err != nil {
624			return fmt.Errorf("failed to create metadata ref: %w", err)
625		}
626	
627		fmt.Fprintf(os.Stderr, "  ✓ Created orphan ref %s for session metadata\n", refs.Primary.Short())
628		return nil
629	}
